240	// Drives the app through its screens, binding only to data-testid (AGENTS.md §2). Every test
241	// arranges its own data with these helpers and asserts through them or through data-testid
242	// directly. An action helper returns what the screen reported: an id when a row was created,
243	// true/false for whether the action went through or the screen refused it (its error element
244	// appeared). It throws when neither a result nor an error shows within the wait, so a screen that
245	// does nothing fails the test instead of passing as "refused".
246	import { expect, test, type Browser, type BrowserContext, type Locator, type Page } from '@playwright/test';
247	import { existsSync, readFileSync } from 'node:fs';
248	
249	const AUDIT_FILE = process.env.AUDIT_FILE ?? '../.run/audit.log';
250	const WAIT = 8000;
251	const LOAD_WAIT = 30000;      // a sign-in, a sheet load or a today change: the whole sheet is re-read
252	const ERROR_GRACE = 2000;     // how long an error left over from the action before may linger
253	const AUDIT_WAIT = 3000;      // how long an audit line may lag the screen
254	
255	const editing = new WeakMap<Page, string>();
256	
257	export function sheetId(): string {
258	  return 's' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
259	}
260	
261	/** The id a creating helper returned; throws when the screen refused (null) so the failure
262	 *  lands on the arranging line rather than on a later assertion. */
263	export function must(id: string | null): string {
264	  if (id === null) throw new Error('the screen refused this action (its error element appeared)');
265	  return id;
266	}
267	
268	function escapeRe(s: string): string {
269	  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
270	}
271	
272	/** The trimmed text of a locator, read without waiting: '' when it is not on the page. A poll
273	 *  must never use an auto-waiting read (textContent, getAttribute) on an element that may be
274	 *  re-rendered or removed while it polls; that read would block until the test's own timeout. */
275	async function shown(loc: Locator): Promise<string> {
276	  return ((await loc.allTextContents())[0] ?? '').trim();
277	}
278	
279	/** The ids carried by every element matching `loc`, read without waiting. */
280	async function ids(loc: Locator, prefix: string): Promise<string[]> {
281	  const out: string[] = [];
282	  for (const h of await loc.elementHandles()) out.push(idOf(await h.getAttribute('data-testid'), prefix));
283	  return out;
284	}
285	
286	/** The rows matching `loc` whose id is not in `before`, in screen order, each with its id and the
287	 *  text of the named cells; read without waiting, so a poll may call it. A creating helper finds
288	 *  its row this way: a page may be showing the sheet as it was when it was loaded, so the rows
289	 *  other users added can land on it at any moment, including between a submit and its result. */
290	async function freshRows(loc: Locator, prefix: string, before: string[], cells: string[]): Promise<Record<string, string>[]> {
291	  const out: Record<string, string>[] = [];
292	  try {
293	    for (const h of await loc.elementHandles()) {
294	      const testid = (await h.getAttribute('data-testid')) ?? '';
295	      if (!testid.startsWith(prefix) || before.includes(testid.slice(prefix.length))) continue;
296	      const x: Record<string, string> = { id: testid.slice(prefix.length) };
297	      for (const c of cells) x[c] = ((await (await h.$(`[data-testid="${c}"]`))?.textContent()) ?? '').trim();
298	      out.push(x);
299	    }
300	  } catch {
301	    return [];                            // a row was re-rendered mid-read: the poll looks again
302	  }
303	  return out;
304	}
305	
306	/** An amount as the screen shows it: two decimals, a dot, no grouping. */
307	function money(amount: string): string {
308	  const n = Number(amount.trim());
309	  return amount.trim() !== '' && Number.isFinite(n) ? n.toFixed(2) : amount;
310	}
311	
312	/** A name as a name cell shows it, without a trailing " (<grade>)" the screen may append. */
313	function plainName(shown: string): string {
314	  return shown.trim().replace(/\s\([^()]*\)$/, '');
315	}
316	
317	/** The id of a person row new since `before` whose name is `name` (case and outer spaces
318	 *  ignored), or null when none shows yet. */
319	async function addedPerson(page: Page, before: string[], name: string): Promise<string | null> {
320	  const want = name.trim().toLowerCase();
321	  const hit = (await freshRows(rows(page), 'person-row-', before, ['person-name'])).find((p) => plainName(p['person-name']).toLowerCase() === want);
322	  return hit ? hit.id : null;
323	}
324	
325	/** The id of a claim row under `scope` new since `before` showing the amount (and the date,
326	 *  when one was given) that was entered, or null when none shows yet; the first in screen order
327	 *  (newest first) when more than one does. */
328	async function addedClaim(scope: Locator, before: string[], f: ClaimFields): Promise<string | null> {
329	  const want = money(f.amount ?? '');
330	  const hit = (await freshRows(claimRows(scope), 'claim-row-', before, ['claim-amount', 'claim-date']))
331	    .find((c) => c['claim-amount'] === want && (f.date === undefined || c['claim-date'] === f.date));
332	  return hit ? hit.id : null;
333	}
334	
335	/** The id of the first claim row under `scope` new since `before`, or null when none shows yet. */
336	async function addedAnyClaim(scope: Locator, before: string[]): Promise<string | null> {
337	  const hit = (await freshRows(claimRows(scope), 'claim-row-', before, []))[0];
338	  return hit ? hit.id : null;
339	}
340	
341	function idOf(testid: string | null, prefix: string): string {
342	  if (!testid || !testid.startsWith(prefix)) throw new Error(`no ${prefix}* id on ${testid}`);
343	  return testid.slice(prefix.length);
344	}
345	
346	/** Poll until `done` holds (true) or `error` is visible (false); throw when neither happens.
347	 *  Each check returns as soon as it can. An error already visible at the first look after the
348	 *  click may be left over from the action before (the screen clears it when a new action is
349	 *  submitted, see README): it counts as this action's refusal once it has gone away and been
350	 *  shown again, once its text changes, or once ERROR_GRACE has passed with no result.
351	 *  `already` says `done` held BEFORE the action (watching a person already watched, saving a
352	 *  setting at its current value): then the result on screen proves nothing, and the action
353	 *  counts as taken only once ERROR_GRACE has passed with no refusal shown. */
354	async function until(page: Page, done: () => Promise<boolean>, error: Locator, what: string,
355	                     already = false): Promise<boolean> {
356	  const deadline = Date.now() + WAIT;
357	  let stale: string | null | undefined;   // text of an error visible at the first look; null if none
358	  let seenGone = false;
359	  const grace = Date.now() + ERROR_GRACE;
360	  while (Date.now() < deadline) {
361	    if (!already && await done()) return true;
362	    const visible = await error.isVisible().catch(() => false);
363	    if (stale === undefined) stale = visible ? await shown(error) : null;
364	    if (visible) {
365	      if (stale === null || seenGone || (await shown(error)) !== stale || Date.now() >= grace) return false;
366	    } else {
367	      seenGone = true;
368	    }
369	    // the state held before the action: an error still showing at the grace outranks it
370	    if (already && Date.now() >= grace && await done()) return true;
371	    await page.waitForTimeout(50);
372	  }
373	  if (await done()) return true;
374	  if (await error.isVisible().catch(() => false)) return false;
375	  throw new Error(`${what}: neither a result nor an error appeared within ${WAIT}ms`);
376	}
377	
378	async function sleep(ms: number): Promise<void> {
379	  await new Promise((r) => setTimeout(r, ms));
380	}
381	
382	/** A counter the screen shows after a bulk action: the number in the cell once it is visible. */
383	async function counter(page: Page, cell: Locator, error: Locator, what: string): Promise<number | null> {
384	  const ok = await until(page, async () => (await cell.count()) > 0 && (await shown(cell)) !== '', error, what);
385	  return ok ? Number(await shown(cell)) : null;
386	}
387	
388	/** Fill a form field, or CLEAR it when the test gives no value. A refused submission leaves what
389	 *  was typed in the form (nothing in the contract says otherwise), so a value left over from the
390	 *  attempt before must never leak into this one: the test states every field it submits. A field
391	 *  the screen does not have is skipped. */
392	async function setField(scope: Locator | Page, testid: string, value: string | undefined): Promise<void> {
393	  const loc = scope.getByTestId(testid);
394	  if (value !== undefined) {
395	    await loc.fill(value);
396	  } else if ((await loc.count()) > 0) {
397	    await loc.fill('');
398	  }
399	}
400	
401	/** The result count a button shows once its action is done (how many were added, made, opened).
402	 *  `was` is what the cell showed before the click. The count is taken once it differs from `was`,
403	 *  or once the cell was seen cleared and shown again (README: a result is cleared when its button
404	 *  is pressed again). Two identical results in a row can look the same on screen for the whole
405	 *  wait: then, with no error showing and a value in the cell, that value is taken rather than
406	 *  failing a step the app did take. */
407	async function countAfter(page: Page, cell: Locator, error: Locator, what: string, was: string): Promise<string | null> {
408	  let cleared = false;
409	  const done = async () => {
410	    if ((await cell.count()) === 0) return false;
411	    const now = await shown(cell);
412	    if (now === '') { cleared = true; return false; }
413	    return now !== was || was === '' || cleared;
414	  };
415	  try {
416	    return (await until(page, done, error, what)) ? await shown(cell) : null;
417	  } catch (e) {
418	    if (await error.isVisible().catch(() => false)) return null;
419	    if ((await cell.count()) > 0 && (await shown(cell)) !== '') return shown(cell);
420	    throw e;
421	  }
422	}
