431	export async function userPage(browser: Browser, user: string, sheet: string): Promise<Page> {
432	  let owner = '';
433	  try { owner = test.info().testId; } catch { /* outside a test: nothing to tidy by */ }
434	  for (const [c, t] of opened) {
435	    if (t === owner) continue;
436	    opened.delete(c);
437	    await c.close().catch(() => { /* already gone */ });
438	  }
439	  const context = await browser.newContext();
440	  opened.set(context, owner);
441	  const page = await context.newPage();
442	  page.setDefaultTimeout(LOAD_WAIT);     // an element an action needs that never shows fails here, not at the test's limit
443	  await page.goto('/');
444	  await page.getByTestId('signin-name').fill(user);
445	  await page.getByTestId('signin-submit').click();
446	  await expect(page.getByTestId('current-user')).toHaveText(user, { timeout: LOAD_WAIT });
447	  await loadSheet(page, sheet);
448	  return page;
449	}
