457	/** Re-load the active sheet so the screen shows what the store holds now. Loading the same id
458	 *  again is not observable (the current id already reads that), so the screen first loads a
459	 *  throwaway id, which has no one on it, and waits for the person rows to go; then it loads the
460	 *  sheet again and waits for rows to show. Rows that were on screen before may rightly not come
461	 *  back (someone retired since, say), so the wait is for any row, and for every row that is back
462	 *  to carry at least the claims it had; if none shows within the wait the screen is taken as it
463	 *  is and the test's own checks decide. The show-retired box and the as-of date, which belong to
464	 *  the screen, are put back if the loads reset them. */
465	export async function refresh(page: Page): Promise<void> {
466	  const sheet = (await page.getByTestId('sheet-current-id').textContent() ?? '').trim();
467	  const before = new Map<string, number>();
468	  for (const id of await ids(rows(page), 'person-row-')) before.set(id, await claimRows(row(page, id)).count());
469	  const retired = page.getByTestId('show-retired');
470	  const showRetiredWas = (await retired.count()) > 0 ? await retired.isChecked() : null;
471	  const asofWas = await shown(page.getByTestId('sheet-asof'));
472	  const previewWas = await shown(page.getByTestId('sheet-preview'));
473	  await loadSheet(page, sheet + '-reload');
474	  await expect.poll(() => rows(page).count(), { message: 'the throwaway sheet, which has no one on it, is on screen', timeout: LOAD_WAIT }).toBe(0);
475	  await loadSheet(page, sheet);
476	  if (showRetiredWas !== null && (await retired.isChecked()) !== showRetiredWas) await retired.setChecked(showRetiredWas);
477	  if (asofWas !== '' && (await shown(page.getByTestId('sheet-asof'))) !== asofWas) await setAsOf(page, asofWas);
478	  if (previewWas !== '' && (await shown(page.getByTestId('sheet-preview'))) !== previewWas) await setPreview(page, previewWas);
479	  if (before.size === 0) return;
480	  const back = async () => {
481	    if ((await rows(page).count()) === 0) return false;
482	    for (const [id, n] of before) {
483	      const r = row(page, id);
484	      if ((await r.count()) > 0 && (await claimRows(r).count()) < n) return false;
485	    }
486	    return true;
487	  };
488	  const deadline = Date.now() + LOAD_WAIT;
489	  while (Date.now() < deadline && !(await back())) await page.waitForTimeout(50);
490	}
