590	export async function editSave(page: Page, f: PersonFields, shows?: Shows): Promise<boolean> {
591	  const id = editing.get(page);
592	  if (!id) throw new Error('editSave without editOpen');
593	  const want = typeof shows === 'string' ? { grade: shows } : (shows ?? {});
594	  const grade = want.grade ?? f.grade;                       // the grade the row shows once saved
595	  const terms = want.terms ?? f.terms;                       // the terms in force the row shows
596	  const r = row(page, id);
597	  const shows_ = async () => {
598	    if (f.name !== undefined && plainName(await shown(r.getByTestId('person-name'))) !== f.name.trim()) return false;
