1027	    const now = await shown(cell);
1028	    if (now === '') { cleared = true; return false; }
1029	    return now !== was || was === '' || cleared;
1030	  };
1031	  const ok = await until(page, async () => (await counted()) || (await claimRows(page).count()) > before,
1032	    page.getByTestId('paste-error'), 'paste claims');
