1066	/** The cells an edit will be judged by, as they are before the save. */
1067	async function editedCells(c: Locator, f: ClaimFields): Promise<Record<string, string>> {
1068	  const out: Record<string, string> = {};
1069	  for (const k of Object.keys(f)) out[k] = await shown(c.getByTestId(`claim-${k}`));
1070	  return out;
1071	}
