1073	/** Whether the row shows the edit: an amount, date, note or corrects cell equal to what was
1074	 *  typed; a ref or tags cell, which the app normalises, is taken as saved once the form's error
1075	 *  is not showing and the cell is no longer what it was (or the typed value, normalised, is a
1076	 *  value it could not have had before). */
1077	async function editedShows(c: Locator, f: ClaimFields, was: Record<string, string>): Promise<boolean> {
1078	  for (const [k, v] of Object.entries(f)) {
1079	    const cell = await shown(c.getByTestId(`claim-${k}`));
1080	    if (k === 'ref' || k === 'tags') {
1081	      const norm = k === 'ref' ? v.trim() : v.split(',').map((t) => t.trim().toLowerCase()).filter((t) => t)
1082	        .filter((t, i, a) => a.indexOf(t) === i).sort().join(', ');
1083	      if (cell !== norm) return false;
1084	    } else if (cell !== v) return false;
1085	  }
1086	  return true;
1087	}
