327	    public SheetRepository(JdbcTemplate jdbc) {
328	        this.jdbc = jdbc;
329	    }
330	
331	    /** The sheet with this id, made empty (its today the real date) when the id was never used. */
332	    public Sheet loadOrCreate(String id, String user) {
333	        Integer known = jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, id);
334	        if (known == null || known == 0) {
335	            try {
336	                jdbc.update("INSERT INTO sheet (id, created_by, today) VALUES (?, ?, ?)", id, user,
337	                        Date.valueOf(LocalDate.now()));
338	            } catch (DuplicateKeyException made) {
339	                // another user loaded the same new id at the same moment: it is made either way
340	            }
341	        }
