439	// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
440	// of a silent `if (res.ok)` that leaves the UI showing stale data. The rejection's message is the
441	// server's own `error` text when it sent one.
442	//
443	// Every request carries the signed-in name in X-User (the server records it as `by=<user>`).
444	let signedInUser = '';
445	
446	/** Called by the session (features/session) whenever the signed-in name changes. */
447	export function setSignedInUser(name: string): void {
448	  signedInUser = name;
449	}
450	
451	async function send<T>(path: string, init?: RequestInit): Promise<T> {
452	  const headers = new Headers(init?.headers);
453	  if (signedInUser) headers.set('X-User', signedInUser);
454	  const res = await fetch(path, { ...init, headers });
455	  if (!res.ok) {
456	    let message = `${init?.method ?? 'GET'} ${path} -> ${res.status}`;
457	    try {
458	      const body = (await res.json()) as { error?: string };
459	      if (body?.error) message = body.error;
460	    } catch {
461	      /* no JSON body: keep the status message */
462	    }
463	    throw new Error(message);
464	  }
465	  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
466	}
467	
468	export function getJson<T>(path: string): Promise<T> {
469	  return send<T>(path);
470	}
471	
472	export function postJson<T>(path: string, body: unknown): Promise<T> {
473	  return send<T>(path, {
474	    method: 'POST',
475	    headers: { 'Content-Type': 'application/json' },
476	    body: JSON.stringify(body),
477	  });
478	}
