527	import type { ComponentType, ReactElement } from 'react';
528	import { forSlot } from './registry';
529	
530	// ── Slots: regions of the UI that features fill ───────────────────────────────────────────────
531	// A SLOT is a region of the UI that features fill. Whatever renders a region does not list what
532	// goes in it; a contribution to a region (a panel, a table column, a row action, a toolbar
533	// control, a nav link) is a separate file, registered by discovery (slots/discover.ts).
534	//
535	//   1. declare a region  ->  slots/defs/projectDetail.ts
536	//        export const ProjectDetail = defineSlot<{ projectId: number }>('project.detail');
537	//   2. render it         ->  <ProjectDetail.Slot projectId={id} />
538	//   3. fill it           ->  features/projects/notes.slot.tsx
539	//        export const contribution = ProjectDetail.fill({ order: 30, Component: ProjectNotes });
540	//
541	// This file, slots/registry.ts and slots/discover.ts implement that mechanism; a region is
542	// declared by a file under slots/defs/.
543	
544	export type Contribution<Ctx> = {
545	  /** Lower renders first; equal orders fall back to file path, so the order is always stable. */
546	  order?: number;
547	  Component: ComponentType<Ctx>;
548	};
549	
550	export type SlotDef<Ctx extends object> = {
551	  id: string;
552	  /** Renders the region. Its props ARE the context handed to every contribution. */
553	  Slot: (ctx: Ctx) => ReactElement;
554	  /** A feature wraps its contribution in this, to be typed against the region's context. */
555	  fill: (contribution: Contribution<Ctx>) => Contribution<Ctx> & { slot: string };
556	};
557	
558	export function defineSlot<Ctx extends object = Record<string, never>>(id: string): SlotDef<Ctx> {
559	  return {
560	    id,
561	    // A Fragment, never a wrapper element: a slot must be usable inside <thead>/<tr> (columns and
562	    // row actions are slots too), where a stray <div> would be invalid markup.
563	    Slot: (ctx: Ctx) =>
564	      createElement(
565	        Fragment,
566	        null,
567	        forSlot(id).map((c) =>
568	          createElement(c.Component as ComponentType<Ctx>, { key: c.from, ...ctx }),
569	        ),
570	      ),
571	    fill: (contribution) => ({ slot: id, ...contribution }),
572	  };
573	}
