808	# In-memory H2 (dies with the JVM = clean per-run reset).
809	spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
810	spring.datasource.driver-class-name=org.h2.Driver
811	spring.datasource.username=sa
812	spring.datasource.password=
813	# Pooled connections are never retired: when HikariCP closes one at its default 30 min
814	# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
815	# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
816	spring.datasource.hikari.max-lifetime=0
